/* Content for the per-term glossary pages (glossary/<id>.html).
 *
 * The definition itself is NOT here: gen-glossary-pages.mjs reads it from
 * glossary.html, so the term page and the glossary entry cannot disagree. What
 * is here is what a one-paragraph glossary entry has no room for -- how the
 * term is used in practice, the points people get wrong, and where to go next.
 *
 * Only terms with an entry below get a page. The oil-and-gas and general
 * mechanical terms in the glossary (API 5CT, BOP, OCTG, preload and the rest)
 * are deliberately left on the glossary page alone: the site no longer covers
 * that sector, and a page per term there would be thin and off-subject.
 *
 * The four tax and trade-policy terms are kept short on purpose and point to
 * the guides. Those rules change, and a glossary page is the wrong place to
 * carry figures or dates that go stale.
 */
const G = (slug, label) => [`${slug}.html`, label];
const C = (slug, label) => [`calculators/${slug}.html`, label];
const H = (slug, label) => [`charts/${slug}.html`, label];

export const TERMS = {
'ampacity': {
  more: ['Ampacity is not a property of the wire alone. The same conductor has a different ampacity in free air, in a conduit with two others, in a conduit with eight others, and in a hot attic. The published figure assumes a stated ambient temperature and no more than three current-carrying conductors together, and each departure from those conditions lowers it.',
         'There is also a second limit that has nothing to do with the conductor. Equipment terminals are rated for 60 or 75&deg;C, and the circuit is limited by the lowest-rated termination in it. A conductor insulated for 90&deg;C can use its higher rating for derating arithmetic, but it still has to be sized so the terminal stays within its own limit.'],
  points: ['Ampacity is a thermal limit: it is the current at which the insulation reaches its rated temperature.', 'Two checks decide a conductor size, the termination rating and the derated ampacity, and the larger answer governs.', 'On long runs voltage drop, not ampacity, usually sets the size.'],
  links: [C('wire-size', 'Wire Size Calculator'), G('guide-cable-ampacity-derating', 'Cable Ampacity Derating'), C('ampacity', 'Cable Ampacity &amp; Conduit Fill'), H('awg-wire-size-chart', 'AWG Wire Size Chart')],
  see: ['derating', 'interrupting-rating'],
},
'ansi-c57': {
  more: ['C57 is a family, not a single document. C57.12.00 sets general requirements for liquid-immersed transformers and C57.12.01 does the same for dry-type units; C57.12.90 and C57.12.91 are the test codes; C57.91 and C57.96 are the loading guides; and further parts cover bushings, tap changers, terminal markings and sound levels.',
         'A specification that says only "to ANSI C57" has said very little. The useful ones name the part that applies and then state what the standard leaves to the purchaser: impedance, insulation level, temperature rise, cooling class, sound level and the tests to be witnessed.'],
  points: ['The standards are published by IEEE and approved as American National Standards, which is why both names appear.', 'Outside North America the equivalent family is IEC 60076, and the two differ in ratings, test levels and notation.'],
  links: [G('guide-transformer-nameplate', 'How to Read a Transformer Nameplate'), ['data-centers/transformers.html', 'Data Center Transformers'], G('guide-transformer-impedance', 'Transformer Impedance (%Z)'), G('guide-pad-mount-vs-gsu-transformers', 'Pad-Mount vs. GSU Transformers')],
  see: ['bil', 'impedance', 'vector-group', 'gsu'],
},
'arc-flash-boundary': {
  more: ['The boundary is a distance, and it comes out of the same calculation that produces incident energy. Incident energy falls off with distance from the arc, so there is always some distance at which it has dropped to 1.2 cal/cm&sup2;. Inside that distance, anyone present needs arc-rated protection; outside it, they do not.',
         'It is separate from the shock boundaries. The limited and restricted approach boundaries protect against touching or arcing over to a live part and depend on voltage. The arc-flash boundary protects against heat and depends on fault current and clearing time. On a system with high fault current and slow protection, the arc-flash boundary can be many feet beyond either shock boundary.'],
  points: ['Faster clearing shrinks the boundary. So does more distance from the arc; so does lower fault current, up to the point where lower current makes the protection slower.', 'The boundary on a label is only valid for the system as it was studied. A changed transformer or relay setting can move it.'],
  links: [G('guide-arc-flash-boundary-basics', 'Arc-Flash Boundary Basics'), C('arc-flash', 'Arc-Flash Calculator'), G('guide-arc-flash-ppe-categories', 'Arc-Flash PPE Categories'), G('guide-nec-240-87-arc-energy-reduction', 'NEC 240.87 Arc Energy Reduction')],
  see: ['incident-energy', 'nfpa-70e', 'interrupting-rating'],
},
'ats-sts': {
  t: 'ATS vs. STS: Transfer Switches Compared',
  more: ['The difference is measured in milliseconds, and it only matters relative to what the load can ride through. A mechanical automatic transfer switch moves contacts and typically takes tens of milliseconds to several seconds, depending on whether it transfers open or closed and whether it waits for a generator. A static transfer switch uses solid-state devices and transfers in about a quarter of a cycle, which is around 4 ms at 60 Hz.',
         'IT power supplies are generally designed to ride through roughly 10 to 20 ms of lost input. That places a static switch inside the ride-through window and a mechanical one outside it, which is why an ATS normally sits upstream of a UPS, where the UPS covers the gap, and an STS sits downstream, between two already-conditioned sources.'],
  points: ['An ATS chooses between utility and generator. An STS chooses between two live sources that are both already available.', 'A static switch can only transfer cleanly between sources that are in phase with each other, or close to it.'],
  links: [G('guide-ats-vs-sts-vs-static-bypass', 'ATS vs. STS vs. Static Bypass'), G('guide-ups-topologies', 'UPS Topologies'), ['data-centers/backup-power.html', 'Backup Power Equipment'], G('guide-n-plus-1-vs-2n-redundancy', 'N+1 vs. 2N Redundancy')],
  see: ['n-plus-1', 'black-start'],
},
'augmentation': {
  t: 'BESS Augmentation: Definition',
  more: ['Lithium-ion cells lose capacity with every cycle and with age. A storage project that has to deliver a fixed amount of energy for fifteen or twenty years can meet that in two ways: install enough extra capacity on day one to still be adequate at the end, or install less and add to it later. The second is augmentation.',
         'It has to be designed for at the start. The site needs space, foundations and spare electrical capacity for the later blocks, and the power conversion and controls have to cope with new cells working beside aged ones, which do not share the same voltage or resistance. Projects that leave this to be solved later often find the additions have to go on their own inverters.'],
  points: ['The alternative, oversizing at the start, spends capital years before it earns anything and ages the spare capacity anyway.', 'Augmentation schedules are tied to the degradation curve in the supply warranty, so the two are negotiated together.'],
  links: [G('guide-bess-augmentation', 'BESS Augmentation'), C('bess-sizing', 'BESS Sizing Calculator'), G('guide-bess-c-rate', 'BESS C-Rate Explained'), ['battery-storage/bess-enclosures.html', 'BESS Enclosures']],
  see: ['dc-block', 'soc-soh', 'c-rate', 'lfp-nmc'],
},
'backtracking': {
  more: ['A single-axis tracker follows the sun from east to west. Early and late in the day the sun is low, and a row tilted steeply toward it casts a long shadow onto the row behind. Because the cells in a module are wired in series, shading a strip along the bottom can cut the output of the whole string far more than the shaded area suggests.',
         'Backtracking avoids this by flattening the rows just enough that each one\'s shadow lands in the gap and not on its neighbour. The modules are no longer pointed straight at the sun, so they collect a little less direct light, but they collect it across the whole string. On sloping or uneven ground the simple calculation fails, and terrain-aware backtracking adjusts each row for the height of the one next to it.'],
  points: ['How much backtracking is needed depends on the ground coverage ratio: the tighter the rows, the more it is used.', 'Bifacial modules change the optimum, because flattening the rows also changes what reaches the rear face.'],
  links: [['renewables/dc-collection.html', 'DC Collection Equipment'], C('solar-string', 'Solar String Sizing Calculator'), G('guide-inverter-clipping-ratio', 'Inverter Clipping &amp; DC:AC Ratio'), ['renewables.html', 'Renewables Equipment']],
  see: ['bifacial-gain', 'mppt', 'bos'],
},
'bifacial-gain': {
  more: ['A bifacial module has cells that respond to light from both sides and a transparent back in place of an opaque backsheet. The front works as any module does. The rear picks up light reflected from the ground and scattered from the sky, and the extra energy is the bifacial gain, quoted as a percentage over the same module working from the front alone.',
         'The module has a fixed bifaciality factor, the ratio of rear to front efficiency, commonly somewhere around 0.7 to 0.8 depending on the cell technology. The gain at a site is a different thing and is mostly a property of the installation: how reflective the ground is, how high the modules sit, how far apart the rows are, and how much of the rear is shaded by the mounting structure.'],
  points: ['Pale gravel or snow raises the gain; dark soil or vegetation lowers it.', 'The extra current has to be allowed for when sizing strings, fuses and conductors.'],
  links: [C('solar-string', 'Solar String Sizing Calculator'), C('dc-ac-ratio', 'DC/AC Ratio Calculator'), ['renewables/dc-collection.html', 'DC Collection Equipment'], G('guide-inverter-clipping-ratio', 'Inverter Clipping &amp; DC:AC Ratio')],
  see: ['backtracking', 'clipping', 'dc-ac-ratio', 'mppt'],
},
'bil': {
  t: 'BIL (Basic Insulation Level): Definition',
  more: ['Insulation has to survive two different things: the steady voltage it works at, and brief surges many times higher caused by lightning and switching. BIL is the rating for the second. It is established by test, by applying a standard impulse wave that rises to its peak in 1.2 microseconds and decays to half in 50, and it is stated as the peak of that wave in kilovolts.',
         'Each voltage class has a small set of standard BIL values to choose from. A 15 kV class transformer, for example, is commonly built to 95 or 110 kV BIL. The higher value costs more and buys margin; which one is right depends on how exposed the equipment is to surges and how well it is protected by surge arresters. The arrester and the BIL are chosen together, a process called insulation coordination.'],
  points: ['BIL is a peak impulse value, not an rms working voltage, which is why it looks so much larger than the system voltage.', 'Altitude reduces the strength of air insulation, so external BIL is derated above about 1,000 m.'],
  links: [G('guide-transformer-nameplate', 'How to Read a Transformer Nameplate'), ['data-centers/transformers.html', 'Data Center Transformers'], G('guide-switchgear-compartments', 'Switchgear Compartments'), G('guide-pad-mount-vs-gsu-transformers', 'Pad-Mount vs. GSU Transformers')],
  see: ['ansi-c57', 'impedance', 'vector-group', 'metal-clad'],
},
'black-start': {
  more: ['Most generation needs a live grid before it can start. Large plants need power for their own pumps and controls, and most inverters need a voltage waveform to lock onto. After a wide blackout something has to go first, energize a dead line, and give the next unit a grid to start against. Sources able to do that are black-start resources.',
         'Traditionally these were hydro plants and small diesel or gas units. Battery storage with grid-forming inverters is now used as well, because it can create its own voltage and frequency. The difficult part is not starting but picking up load: energizing a transformer or a long cable draws a large inrush, and the black-start source has to supply it without collapsing.'],
  points: ['A facility with its own generators and a UPS performs a small black start every time it recovers from a utility outage.', 'Black-start capability is specified and tested; it is not implied by a grid-forming label alone.'],
  links: [G('guide-grid-forming-vs-grid-following', 'Grid-Forming vs. Grid-Following Inverters'), ['battery-storage/pcs-inverters.html', 'PCS &amp; Inverters'], C('inrush', 'Transformer Inrush Calculator'), G('guide-generator-sizing', 'Generator Sizing')],
  see: ['grid-forming', 'pcs', 'ats-sts'],
},
'bos': {
  t: 'BOS (Balance of System): Definition',
  more: ['On a solar project the modules are one line in the budget and everything else is balance of system: the racking or trackers, the combiner boxes and DC cabling, the inverters, the AC collection system, transformers, switchgear, monitoring and the grounding. On a storage project the term covers what surrounds the battery enclosures in the same way.',
         'As module prices have fallen, balance of system has become the larger share of what a plant costs, and it is where most of the engineering choices are made. Voltage level, string length, inverter type and DC:AC ratio are all balance-of-system decisions, and each trades equipment cost against losses over the life of the plant.'],
  points: ['Structural and electrical BOS are often separated, because they are bought from different suppliers and installed by different trades.', 'Soft costs such as permitting and interconnection are sometimes counted with BOS and sometimes not, so check what a quoted figure includes.'],
  links: [['renewables.html', 'Renewables Equipment'], ['renewables/dc-collection.html', 'DC Collection'], ['renewables/ac-collection.html', 'AC Collection'], ['battery-storage/balance-of-plant.html', 'BESS Balance of Plant']],
  see: ['mppt', 'dc-ac-ratio', 'pcs', 'backtracking'],
},
'busway': {
  t: 'Busway (Bus Duct): Definition',
  more: ['Busway is a factory-made assembly of copper or aluminum bars inside a grounded metal housing, supplied in sections that bolt together. It does the job of a set of large cables in conduit, and above a few hundred amps it is usually more compact and has a lower voltage drop for the same current.',
         'In a data hall the plug-in type is run above the rows of racks. Each rack is fed from a tap-off box that plugs into the busway and carries its own breaker, so adding or moving a rack means fitting a tap-off and not pulling a new circuit from a distant panel. That flexibility is the reason overhead busway has replaced underfloor cabling in many facilities.'],
  points: ['Busway has a short-circuit rating as an assembly, which has to exceed the available fault current where it is installed.', 'Voltage drop is published per 100 ft at rated current and should be checked on long runs.'],
  links: [['data-centers/power-distribution.html', 'Power Distribution Equipment'], G('guide-rack-power-density', 'Rack Power Density'), G('guide-415v-vs-480v-distribution', '415 V vs. 480 V Distribution'), C('voltage-drop', 'Voltage Drop Calculator')],
  see: ['sccr', 'mccb', 'ampacity'],
},
'cdu': {
  t: 'CDU (Coolant Distribution Unit): Definition',
  more: ['Liquid-cooled servers have small passages in their cold plates that would foul or corrode on ordinary building water. A coolant distribution unit keeps the two apart. It contains a heat exchanger, pumps, filtration and controls, and it circulates a clean, treated fluid through the IT equipment while rejecting the heat to the facility water on the other side.',
         'It also controls temperature. The fluid sent to the equipment has to stay above the dew point of the room air, or water will condense on the pipework, so the CDU holds its supply temperature above that limit whatever the facility loop is doing. Units come in two forms: in-rack units that serve one cabinet, and larger row or floor units that serve many through a manifold.'],
  points: ['Because the secondary loop can run warm, facility water for liquid cooling can often be produced without chillers for much of the year.', 'Capacity is quoted at a stated approach temperature; a closer approach means less capacity from the same unit.'],
  links: [G('guide-liquid-vs-air-cooling', 'Liquid vs. Air Cooling'), ['data-centers/cooling.html', 'Data Center Cooling Equipment'], C('chilled-water-flow', 'Chilled Water Flow Calculator'), C('pump-power', 'Pump Power Calculator')],
  see: ['crah-crac', 'pue', 'n-plus-1'],
},
'clipping': {
  t: 'Inverter Clipping: Definition',
  more: ['An inverter has a maximum AC output. When the array could supply more than that, the inverter moves its operating point away from the maximum power point, the array delivers less, and the output curve flattens at the inverter\'s rating. Seen on a plot of a clear day, the top of the bell curve is cut off level, which is where the name comes from.',
         'Nothing is damaged and nothing is dumped as heat; the energy is simply never produced. Designers accept this because an array almost never reaches its nameplate output, so an inverter sized to match nameplate would spend nearly all its life part-loaded. A larger array on the same inverter gives up a little at midday in summer and gains through the mornings, evenings and winter.'],
  points: ['The clipped fraction of annual energy is usually far smaller than the DC:AC ratio suggests.', 'DC-coupled storage can capture energy that would otherwise be clipped.'],
  links: [G('guide-inverter-clipping-ratio', 'Inverter Clipping &amp; DC:AC Ratio'), C('dc-ac-ratio', 'DC/AC Ratio Calculator'), ['renewables/solar-inverters.html', 'Solar Inverters'], C('solar-string', 'Solar String Sizing Calculator')],
  see: ['dc-ac-ratio', 'mppt', 'bifacial-gain', 'bos'],
},
'crah-crac': {
  t: 'CRAH vs. CRAC: Definition',
  more: ['The whole difference is where the cold is made. A computer room air conditioner has a compressor and a refrigerant circuit inside the cabinet and rejects its heat to an outdoor condenser or a pumped loop. A computer room air handler has only a coil, fans and a control valve, and takes chilled water from a central plant.',
         'That one difference drives the rest. CRAC units are independent, so each fails alone, and they suit rooms with no chiller plant. CRAH units depend on the plant behind them, so their redundancy has to be built into the chillers, pumps and pipework, but at scale the plant is more efficient and can use free cooling for much of the year.'],
  points: ['Both are rated on sensible cooling at a stated return air temperature, and deliver less if cold air is allowed to mix into the return.', 'CRAH fans draw little enough to be kept on a UPS; compressors generally are not.'],
  links: [G('guide-crac-vs-crah', 'CRAC vs. CRAH'), G('guide-hot-aisle-vs-cold-aisle-containment', 'Hot Aisle vs. Cold Aisle Containment'), C('airflow-cfm', 'Airflow (CFM) Calculator'), H('cooling-load-chart', 'Cooling Load Chart')],
  see: ['cdu', 'pue', 'n-plus-1'],
},
'c-rate': {
  t: 'C-Rate: Definition and Examples',
  more: ['C-rate normalizes current to the size of the battery, so that cells of different sizes can be compared. A 100 Ah cell discharged at 100 A is at 1C; the same cell at 25 A is at 0.25C. For a whole system it is easier to think in power and energy: a 100 MW, 400 MWh project is a 0.25C system, more often described as four-hour storage.',
         'The rate matters because batteries are less efficient and age faster when worked hard. A high C-rate means more heat in the cells, more capacity that cannot be reached before the voltage limit, and more cooling. Cells are designed toward one end or the other: energy cells for long, gentle discharges and power cells for short, intense ones, and using either outside its range shortens its life.'],
  points: ['Duration in hours is one divided by the C-rate.', 'Charge and discharge rates are specified separately and are often not equal.'],
  links: [G('guide-bess-c-rate', 'BESS C-Rate Explained'), C('bess-sizing', 'BESS Sizing Calculator'), C('battery-runtime', 'Battery Runtime Calculator'), C('ah-to-kwh', 'Ah to kWh Calculator')],
  see: ['soc-soh', 'lfp-nmc', 'augmentation', 'dc-block'],
},
'dc-block': {
  t: 'DC Block (BESS): Definition',
  more: ['A DC block is the battery part of a storage system delivered as one factory-built unit: cells assembled into modules, modules into racks, and racks into an enclosure with its own battery management, thermal management, and fire detection and suppression. It has DC terminals and communications, and it is connected on site to a separate power conversion system.',
         'Building the battery this way moves most of the assembly and testing into the factory and turns site work into placing enclosures and connecting them. It also fixes the unit of expansion: capacity is added a block at a time, which is how both initial sizing and later augmentation are planned.'],
  points: ['The alternative arrangement is an AC block, which includes the inverter in the same enclosure and has AC terminals.', 'Energy per enclosure has risen steadily, so the same site area now holds considerably more than it did a few years ago.'],
  links: [['battery-storage/bess-enclosures.html', 'BESS Enclosures'], G('guide-bess-augmentation', 'BESS Augmentation'), G('guide-bess-fire-safety-nfpa-855', 'BESS Fire Safety: NFPA 855'), C('bess-sizing', 'BESS Sizing Calculator')],
  see: ['pcs', 'augmentation', 'lfp-nmc', 'ul-9540a'],
},
'dc-ac-ratio': {
  t: 'DC:AC Ratio: Definition',
  more: ['Divide the total nameplate power of the modules by the AC rating of the inverter and the result is the DC:AC ratio, also called the inverter loading ratio. A 130 MW array on 100 MW of inverters has a ratio of 1.3.',
         'It is above 1.0 on nearly every modern plant because module nameplate is measured under test conditions the field rarely matches. Heat, the angle of the sun, soiling and wiring losses mean the array usually delivers well under its rating, and an inverter sized to nameplate would be oversized for most of its working life. Raising the ratio fills the inverter for more hours at the cost of some clipping on the best days.'],
  points: ['The economic optimum depends on the relative price of modules and inverters, the site\'s climate and any limit on export.', 'The ratio falls slowly over the life of the plant as the modules degrade.'],
  links: [C('dc-ac-ratio', 'DC/AC Ratio Calculator'), G('guide-inverter-clipping-ratio', 'Inverter Clipping &amp; DC:AC Ratio'), ['renewables/solar-inverters.html', 'Solar Inverters'], C('solar-string', 'Solar String Sizing Calculator')],
  see: ['clipping', 'mppt', 'bifacial-gain', 'bos'],
},
'derating': {
  more: ['Every rating is a statement about test conditions. A conductor\'s ampacity assumes a certain ambient temperature and a certain number of neighbours. A transformer\'s kVA assumes an altitude and an ambient. A generator\'s output assumes air at a given temperature and density. Install the equipment anywhere else and the true capability is lower, and derating is the arithmetic that finds it.',
         'The factors multiply. A cable in a hot space with several others in the same raceway takes a temperature correction and a bundling adjustment, one applied on top of the other, and can end up carrying little more than half its table value. This is the usual reason an installed conductor is larger than a quick lookup suggests.'],
  points: ['Derating can be for the environment (heat, altitude), for the installation (bundling, enclosure) or for the load (harmonics, duty cycle).', 'It is not the same as a safety margin. It restores the equipment to the conditions its rating assumed.'],
  links: [G('guide-cable-ampacity-derating', 'Cable Ampacity Derating'), C('wire-size', 'Wire Size Calculator'), G('guide-continuous-load-80-percent-rule', 'The 80% Rule &amp; Continuous Loads'), C('voltage-unbalance', 'Voltage Unbalance Calculator')],
  see: ['ampacity', 'k-factor', 'bil'],
},
'domestic-content-bonus': {
  more: ['This is a matter of US tax law, and the thresholds, the percentages and the list of what counts have been revised more than once by legislation and by Treasury guidance. A glossary entry is the wrong place to rely on for the current figures.',
         'What stays constant is the structure. The bonus is an addition to a base credit; it is tested separately for structural steel and iron and for manufactured products; and it is a different test from the foreign-entity rules, so a project can pass one and fail the other. Whether a project qualifies is decided from supplier documentation, which is why the question reaches equipment specifications at all.'],
  points: ['Check current Treasury and IRS guidance, or a tax adviser, before relying on any figure.', 'Supplier certifications have to be collected during procurement; they are hard to reconstruct afterwards.'],
  links: [G('guide-feoc-compliance', 'FEOC Compliance'), G('guide-buy-america-iija', 'Buy America &amp; BABA'), G('guide-transformer-lead-times', 'Transformer Lead Times')],
  see: ['feoc', 'itc', 'safe-harbor'],
},
'dry-type': {
  t: 'Dry-Type vs. Liquid-Filled Transformers',
  more: ['A liquid-filled transformer sits in a tank of mineral oil or a less flammable fluid. The liquid insulates the windings and carries their heat to the tank walls and radiators. A dry-type transformer has no liquid: its windings are insulated with varnish or cast in resin and cooled by air moving over them.',
         'Liquid is the better coolant and the better insulator, so liquid-filled units are smaller, more efficient and longer-lived for a given rating, and they dominate above a few MVA and outdoors. The liquid is also the drawback indoors, where it brings requirements for containment and fire separation. Dry-type units avoid those and are the usual choice inside buildings, at the cost of size, losses and a lower tolerance for overload.'],
  points: ['Less-flammable fluids such as natural esters allow liquid-filled units in some indoor locations that mineral oil does not.', 'Dry-type units need clean, dry air; dust and moisture on the windings shorten their life.'],
  links: [['data-centers/transformers.html', 'Data Center Transformers'], G('guide-transformer-nameplate', 'How to Read a Transformer Nameplate'), C('transformer-sizing', 'Transformer Sizing Calculator'), G('guide-pad-mount-vs-gsu-transformers', 'Pad-Mount vs. GSU Transformers')],
  see: ['k-factor', 'impedance', 'gsu', 'goes'],
},
'feoc': {
  t: 'FEOC (Foreign Entity of Concern): Definition',
  more: ['The term comes from US legislation that restricts tax credits where equipment or materials come from companies owned by, controlled by or subject to the jurisdiction of certain foreign governments. The detailed tests, the effective dates and the names used for the restricted categories have changed with successive laws and guidance, so current sources should be checked before any decision is made.',
         'For an engineer the practical effect is on specifications and procurement. Eligibility turns on who made a component and who owns that manufacturer, sometimes several tiers down the supply chain, so a specification that is silent on origin can leave the project without the documents it later needs.'],
  points: ['The rules are separate from domestic content requirements, though the same supplier documents often serve both.', 'This is tax and trade law; confirm the position with current guidance or an adviser.'],
  links: [G('guide-feoc-compliance', 'FEOC Compliance'), G('guide-buy-america-iija', 'Buy America &amp; BABA'), ['battery-storage.html', 'Battery Storage Systems']],
  see: ['itc', 'domestic-content-bonus', 'safe-harbor'],
},
'goes': {
  t: 'GOES (Grain-Oriented Electrical Steel)',
  more: ['A transformer core is magnetized and demagnetized every cycle, and the energy lost in doing so is drawn from the supply whether or not the transformer is carrying load. Grain-oriented steel reduces that loss. The steel is rolled and annealed so that its crystal grains line up along the rolling direction, and it magnetizes much more easily along that direction than across it. Cores are built so the flux follows the grain.',
         'The steel is made in thin sheets, each coated with insulation, and stacked or wound to form the core. Higher grades have thinner sheets and lower losses. Production needs specialized mills, and few plants make it, which has made supply a recurring constraint on how fast transformers can be built.'],
  points: ['Core loss is present all the time, so it matters most for transformers that are lightly loaded for much of their lives.', 'Amorphous metal is an alternative core material with lower loss, used mainly in distribution transformers.'],
  links: [G('guide-transformer-lead-times', 'Why Transformer Lead Times Stretch'), ['lead-time-index.html', 'Lead-Time Index'], ['data-centers/transformer-components.html', 'Transformer Components'], ['calculators/project-finance.html', 'Transformer Loss Cost Calculator']],
  see: ['ansi-c57', 'dry-type', 'k-factor'],
},
'grid-forming': {
  t: 'Grid-Forming vs. Grid-Following: Definition',
  more: ['A grid-following inverter measures the voltage it is connected to, locks onto it, and injects current in step with it. It behaves as a controlled current source and needs a grid to exist first. A grid-forming inverter behaves as a voltage source: it sets its own voltage and frequency and lets the current be whatever the system demands, as a synchronous generator does.',
         'For years almost all inverters were grid-following, which worked while conventional generators set the voltage. As inverter-based generation grows and synchronous machines retire, parts of the grid become weak, meaning the voltage moves easily when current changes, and grid-following controls can become unstable there. Grid-forming inverters hold the voltage steady in those conditions and can restart a dead system.'],
  points: ['Grid-forming is a control method, and largely a matter of firmware; the power hardware is similar.', 'A grid-forming inverter can only help with a disturbance if it has energy and current headroom in reserve at the time.'],
  links: [G('guide-grid-forming-vs-grid-following', 'Grid-Forming vs. Grid-Following Inverters'), ['battery-storage/pcs-inverters.html', 'PCS &amp; Inverters'], G('guide-grid-interconnection-process', 'The Grid Interconnection Process'), ['renewables/solar-inverters.html', 'Solar Inverters']],
  see: ['black-start', 'pcs', 'mppt'],
},
'gsu': {
  t: 'GSU Transformer (Generator Step-Up)',
  more: ['Generators and inverters produce power at a few hundred volts to a few tens of kilovolts. Sending it any distance at that voltage would need enormous conductors, so it is stepped up first. The generator step-up transformer does this, taking the output of a generator, or the collected output of a solar or storage plant, up to the voltage of the transmission line.',
         'It is usually the largest and longest-lead single item on a generating site, and everything the plant produces passes through it. On a renewable plant it stands in the project substation, fed at collection voltage, commonly 34.5 kV in North America, and connected on its high side to the utility. Its impedance, tap range and winding connection are set largely by the interconnection requirements.'],
  points: ['A GSU on a solar or storage plant sees power flow in both directions and a daily load cycle, unlike a conventional station unit.', 'Loss evaluation matters more than on most transformers, because every kilowatt lost is a kilowatt not sold.'],
  links: [G('guide-pad-mount-vs-gsu-transformers', 'Pad-Mount vs. GSU Transformers'), G('guide-transformer-lead-times', 'Why Transformer Lead Times Stretch'), ['renewables/ac-collection.html', 'AC Collection'], G('guide-grid-interconnection-process', 'The Grid Interconnection Process')],
  see: ['impedance', 'vector-group', 'bil', 'goes'],
},
'impedance': {
  t: 'Transformer Impedance (%Z): Definition',
  more: ['Percent impedance is measured in a simple test. The secondary winding is short-circuited and the primary voltage is raised from zero until rated current flows. The voltage needed, as a percentage of rated voltage, is the impedance. A 5.75 percent transformer circulates full-load current into a short circuit with only 5.75 percent of rated voltage applied.',
         'Turn that round and it gives the fault current. With full voltage applied, the current into a short circuit is the full-load current divided by the impedance as a fraction: about 17 times full load at 5.75 percent. Lower impedance means more fault current and tighter voltage regulation; higher impedance means less fault current and more voltage drop under load. The choice is a trade between those two.'],
  points: ['Fault current at the secondary terminals is roughly full-load amps &divide; (%Z &divide; 100), ignoring the source.', 'Transformers can share load in parallel only if their impedances are closely matched.'],
  links: [G('guide-transformer-impedance', 'Transformer Impedance (%Z) Explained'), C('fault-current', 'Fault Current Calculator'), H('kva-to-amps-chart', 'kVA to Amps Chart'), G('guide-transformer-nameplate', 'How to Read a Transformer Nameplate')],
  see: ['interrupting-rating', 'sccr', 'kva-vs-kw', 'goes'],
},
'incident-energy': {
  more: ['An arcing fault releases heat, light and pressure. Incident energy is the heat part, expressed as energy arriving per unit area at a stated working distance, typically 18 inches for low-voltage equipment. It is the number an arc-flash study exists to produce, and protective clothing is selected so that its arc rating is at least the incident energy at the task.',
         'Two things dominate it. One is the arcing current, which follows from the available fault current. The other is how long the arc lasts, which is how long the upstream protective device takes to clear. Energy is proportional to time, so halving the clearing time halves the incident energy. This is why relay settings and maintenance switches have as much effect on the result as the equipment itself.'],
  points: ['Lower fault current is not always safer: it can drop the arc below a breaker\'s instantaneous pickup and make the clearing time much longer.', 'The value applies at the stated working distance and rises steeply closer in.'],
  links: [C('arc-flash', 'Arc-Flash Calculator'), G('guide-arc-flash-boundary-basics', 'Arc-Flash Boundary Basics'), G('guide-arc-flash-ppe-categories', 'Arc-Flash PPE Categories'), G('guide-nec-240-87-arc-energy-reduction', 'NEC 240.87 Arc Energy Reduction')],
  see: ['arc-flash-boundary', 'nfpa-70e', 'selective-coordination', 'interrupting-rating'],
},
'interrupting-rating': {
  t: 'Interrupting Rating (AIC): Definition',
  more: ['A breaker or fuse has two unrelated current ratings. The ampere rating is what it carries all day. The interrupting rating is the largest fault current it can stop without failing, and it is tens or hundreds of times bigger: a 100 A breaker might carry an interrupting rating of 10, 22, 35 or 65 kA.',
         'The requirement is simple to state. The interrupting rating must be at least the fault current available at the point where the device is installed. That available current depends on the supply, mainly the size and impedance of the upstream transformer and the length of conductor in between, so the same breaker can be adequate in one building and dangerous in another.'],
  points: ['AIC and kAIC are the same quantity in amperes and kiloamperes.', 'Replacing a transformer with a larger or lower-impedance one raises the available fault current, and can leave existing breakers under-rated.'],
  links: [G('guide-interrupting-rating-vs-sccr', 'Interrupting Rating vs. SCCR'), C('fault-current', 'Fault Current Calculator'), G('guide-fully-rated-vs-series-rated', 'Fully Rated vs. Series Rated'), H('breaker-size-chart', 'Breaker Size Chart')],
  see: ['sccr', 'impedance', 'mccb', 'selective-coordination'],
},
'itc': {
  t: 'ITC (Investment Tax Credit): Definition',
  more: ['The investment tax credit lets the owner of a qualifying energy project take a percentage of its eligible cost as a credit against federal income tax. It has been a central part of how solar and storage projects in the United States are financed.',
         'The rate, the technologies that qualify, the deadlines for starting construction and the conditions attached have all been changed by legislation more than once, and they are further shaped by Treasury and IRS guidance. Anything stated here as a figure would risk being out of date, so this page does not give one. For engineering purposes the point is that eligibility can depend on equipment origin, on labour requirements and on when construction began, and those reach back into specification and scheduling.'],
  points: ['Confirm current rates and deadlines against IRS guidance or with a tax adviser.', 'The production tax credit is the alternative for some technologies, paid on energy generated instead of on cost.'],
  links: [G('guide-feoc-compliance', 'FEOC Compliance'), G('guide-buy-america-iija', 'Buy America &amp; BABA'), ['calculators/project-finance.html', 'Project Finance Calculators']],
  see: ['feoc', 'domestic-content-bonus', 'safe-harbor'],
},
'k-factor': {
  t: 'K-Factor Transformer: Definition',
  more: ['Loads such as computer power supplies and variable speed drives draw current in pulses, and that current contains harmonics: components at multiples of the supply frequency. Eddy-current losses in transformer windings rise with the square of frequency, so harmonic current heats a transformer far more than the same rms current at 60 Hz would.',
         'The K-factor puts a number on that. It is calculated from the harmonic spectrum of the load, weighting each harmonic by the square of its order, and a K-rated transformer is built to carry a load of that K-factor at full nameplate current without overheating. A K-1 unit is an ordinary transformer; K-4, K-13 and K-20 are progressively more tolerant. They also have an oversized neutral, because third-order harmonics add in it.'],
  points: ['A K-rated transformer withstands harmonics. It does not remove them from the system.', 'The alternative is to derate a standard transformer, which works but gives up capacity.'],
  links: [G('guide-harmonics-ieee-519', 'Harmonics &amp; IEEE 519 Limits'), ['data-centers/transformers.html', 'Data Center Transformers'], G('guide-delta-vs-wye', 'Delta vs. Wye'), C('transformer-sizing', 'Transformer Sizing Calculator')],
  see: ['derating', 'dry-type', 'kva-vs-kw'],
},
'kva-vs-kw': {
  t: 'kVA vs. kW: Definition',
  more: ['kW is the power that does work: it turns the shaft, heats the element, runs the processor. kVA is the product of voltage and current, whether or not all that current is doing work. On AC, loads with motors, transformers or capacitors draw some current that only shuttles energy back and forth, so kVA is always at least as large as kW.',
         'The ratio of the two is the power factor. A load of 400 kW at a power factor of 0.8 is 500 kVA. Equipment that has to carry the current, such as transformers, generators, cables and UPS systems, is limited by kVA, because heating depends on current and not on how useful the current is. Equipment that has to supply energy, such as an engine or a battery, is limited by kW.'],
  points: ['kW = kVA &times; power factor.', 'A UPS has both ratings, and a load can exceed either one first.'],
  links: [G('guide-kw-vs-kva', 'kW vs. kVA Explained'), C('kva-to-kw', 'kVA to kW Converter'), C('power-factor', 'Power Factor Correction Calculator'), H('kva-to-amps-chart', 'kVA to Amps Chart')],
  see: ['impedance', 'k-factor'],
},
'lfp-nmc': {
  t: 'LFP vs. NMC Batteries: Definition',
  more: ['Both are lithium-ion chemistries, named for the cathode material. Lithium iron phosphate has a lower cell voltage, about 3.2 V against about 3.7 V, and stores less energy per kilogram. In exchange its cathode is chemically stable: it releases little oxygen when it breaks down, so a failing cell is less likely to drive its neighbours into thermal runaway, and it tolerates many more charge cycles.',
         'For a vehicle, where weight and volume are scarce, the higher energy density of nickel manganese cobalt has been worth its cost. A stationary system has room and has to last, so the balance goes the other way, and iron phosphate also avoids nickel and cobalt, the two most expensive and supply-constrained ingredients.'],
  points: ['LFP has a very flat voltage curve, which makes state of charge harder to estimate from voltage alone.', 'Neither chemistry is immune to thermal runaway; the fire protection requirements apply to both.'],
  links: [G('guide-bess-fire-safety-nfpa-855', 'BESS Fire Safety: NFPA 855'), ['battery-storage/bess-enclosures.html', 'BESS Enclosures'], G('guide-bess-c-rate', 'BESS C-Rate Explained'), C('ah-to-kwh', 'Ah to kWh Calculator')],
  see: ['soc-soh', 'c-rate', 'ul-9540a', 'nfpa-855'],
},
'mccb': {
  t: 'MCCB (Molded-Case Circuit Breaker)',
  more: ['A molded-case breaker has its contacts, mechanism and trip unit sealed inside an insulating case. It is the breaker found in panelboards and switchboards and feeding most equipment in a commercial or industrial building. It sits between the miniature breakers used on small branch circuits and the large drawout power breakers used in switchgear.',
         'The trip unit decides how it behaves. A thermal-magnetic unit has a bimetal element for overloads and a magnetic element for short circuits, with little adjustment. An electronic unit measures the current and applies adjustable long-time, short-time, instantaneous and ground-fault settings, which is what makes it possible to coordinate one breaker with those above and below it.'],
  points: ['An MCCB is sealed and not meant to be opened or maintained internally; a power breaker is.', 'Unless marked as 100 percent rated, it may carry only 80 percent of its rating continuously.'],
  links: [G('guide-panelboard-vs-switchboard-vs-switchgear', 'Panelboard vs. Switchboard vs. Switchgear'), C('breaker-size', 'Breaker Size Calculator'), G('guide-fuse-vs-breaker', 'Fuse vs. Circuit Breaker'), H('breaker-size-chart', 'Breaker Size Chart')],
  see: ['interrupting-rating', 'sccr', 'selective-coordination', 'metal-clad'],
},
'metal-clad': {
  t: 'Metal-Clad vs. Metal-Enclosed: Definition',
  more: ['Metal-enclosed is the broad term: any switchgear whose live parts are inside a grounded metal housing. Metal-clad is a specific, more demanding construction defined in the standards, used mainly at medium voltage. Every metal-clad lineup is metal-enclosed; most metal-enclosed lineups are not metal-clad.',
         'To be metal-clad, the breakers must be removable, with a mechanism that moves them between connected, test and disconnected positions; the main parts of each circuit must sit in separate compartments divided by grounded metal barriers; shutters must cover the live contacts automatically when a breaker is withdrawn; and the bus must be insulated. Each requirement is there to limit how far a fault can spread and what a person can touch.'],
  points: ['The governing standards are IEEE C37.20.2 for metal-clad and C37.20.3 for metal-enclosed interrupter switchgear.', 'Arc-resistant construction is a further, separate rating and should not be assumed from either term.'],
  links: [G('guide-switchgear-compartments', 'Switchgear Compartments'), ['data-centers/switchgear.html', 'Data Center Switchgear'], G('guide-panelboard-vs-switchboard-vs-switchgear', 'Panelboard vs. Switchboard vs. Switchgear'), G('guide-ansi-device-numbers', 'ANSI Device Numbers')],
  see: ['interrupting-rating', 'bil', 'selective-coordination', 'incident-energy'],
},
'mppt': {
  t: 'MPPT (Maximum Power Point Tracking)',
  more: ['A solar module does not have one output. At any moment it can deliver a range of combinations of voltage and current, and only one of them gives the most power. That point moves as the light and the cell temperature change. A maximum power point tracker is the control loop that keeps finding it, by nudging the operating voltage and watching whether the power rises or falls.',
         'An inverter with a single tracker treats everything connected to it as one array and settles on the best compromise. If part of the array is shaded or faces a different way, the rest is pulled away from its own optimum. Inverters with several independent trackers, and string inverters used in place of one central unit, limit that loss by letting each group of strings find its own point.'],
  points: ['The tracker works only within the inverter\'s MPPT voltage window, which is why string length has to be designed to it.', 'When an inverter clips, it moves deliberately off the maximum power point.'],
  links: [C('solar-string', 'Solar String Sizing Calculator'), ['renewables/solar-inverters.html', 'Solar Inverters'], G('guide-inverter-clipping-ratio', 'Inverter Clipping &amp; DC:AC Ratio'), C('dc-ac-ratio', 'DC/AC Ratio Calculator')],
  see: ['clipping', 'dc-ac-ratio', 'backtracking', 'bifacial-gain'],
},
'n-plus-1': {
  t: 'N+1, N+2 and 2N Redundancy: Definition',
  more: ['N is the number of units needed to carry the load: if the load needs three chillers, N is three. N+1 installs four, so any one can fail or be taken out for maintenance. N+2 installs five. 2N installs two complete, separate systems of three, each able to carry the whole load alone, and 2N+1 adds a spare unit to each.',
         'The notations count units, but what matters is what they protect against. N+1 covers the loss of a unit. It does not cover the loss of something the units share, such as a common pipe header, a single bus or one control system. 2N covers that as well, because nothing is shared between the two sides. That is the real distinction, and it is why 2N costs roughly twice as much and N+1 does not.'],
  points: ['A 2N system runs each side at or below half load, which is less efficient than running one system near full load.', 'Redundancy describes capacity. Whether the system can be maintained without an outage depends on how it is piped and wired.'],
  links: [G('guide-n-plus-1-vs-2n-redundancy', 'N+1 vs. 2N Redundancy'), G('guide-uptime-institute-tiers', 'Uptime Institute Tiers'), G('guide-ups-sizing', 'How to Size a UPS'), ['data-centers.html', 'Data Center Power Equipment']],
  see: ['ats-sts', 'pue', 'crah-crac'],
},
'nfpa-70e': {
  t: 'NFPA 70E: What It Covers',
  more: ['The National Electrical Code, NFPA 70, covers how electrical systems are installed. NFPA 70E covers how people work on them afterwards. Its starting position is that equipment should be put into an electrically safe work condition, de-energized, locked out and verified, before work begins, and that energized work needs a justification and a documented procedure.',
         'Where energized work is done, the standard requires a risk assessment for both shock and arc flash. It defines the approach boundaries, sets out how to choose arc-rated clothing, either from an incident energy analysis or from its task tables, and requires equipment to be labelled with the information a worker needs. In the United States it is the consensus standard that employers use to meet OSHA\'s general requirements for electrical safety.'],
  points: ['NFPA 70E is a work-practice standard, revised on a three-year cycle, and is not itself law.', 'It treats protective equipment as the last control, after de-energizing and engineering measures.'],
  links: [G('guide-arc-flash-ppe-categories', 'Arc-Flash PPE Categories'), G('guide-arc-flash-boundary-basics', 'Arc-Flash Boundary Basics'), C('arc-flash', 'Arc-Flash Calculator'), G('guide-nec-110-26-working-space', 'NEC 110.26 Working Space')],
  see: ['incident-energy', 'arc-flash-boundary', 'interrupting-rating'],
},
'nfpa-855': {
  t: 'NFPA 855: What It Covers',
  more: ['NFPA 855 is the installation standard for stationary energy storage. It applies above stated energy thresholds and covers where a system may be placed, how large each group of batteries may be, how far groups must be separated from each other and from walls and exposures, and what detection, suppression, ventilation and explosion control are required.',
         'Its limits are tied to testing. The default group size and spacing can be exceeded where large-scale fire test data, normally from the UL 9540A method, shows that a fire will not spread from one unit to the next. In practice that makes the test report as important as the standard itself: it is what permits the dense layouts that modern projects use. Fire codes adopt the standard by reference, and the local authority decides how it applies.'],
  points: ['The standard requires a hazard mitigation analysis and an emergency response plan for larger installations.', 'Editions differ; the one that applies is the one the jurisdiction has adopted.'],
  links: [G('guide-bess-fire-safety-nfpa-855', 'BESS Fire Safety: NFPA 855 &amp; UL 9540A'), ['battery-storage/balance-of-plant.html', 'BESS Balance of Plant'], ['battery-storage/bess-enclosures.html', 'BESS Enclosures'], ['battery-storage.html', 'Battery Storage Systems']],
  see: ['ul-9540a', 'lfp-nmc', 'dc-block'],
},
'pcs': {
  t: 'PCS (Power Conversion System): Definition',
  more: ['Batteries store and release direct current. The grid is alternating current. The power conversion system sits between them and works in both directions: as an inverter when the battery discharges and as a rectifier when it charges. It includes the power electronics, filters, protection and cooling, and usually a transformer to match the grid voltage.',
         'It also decides how the plant behaves electrically. The PCS controls real and reactive power, responds to frequency and voltage, rides through grid disturbances as the interconnection rules require, and in grid-forming designs sets the voltage itself. Its power rating in MW and the battery\'s energy rating in MWh are separate choices, and their ratio is the duration of the system.'],
  points: ['A PCS is rated in MVA as well as MW, because it supplies reactive power alongside real power.', 'Round-trip efficiency includes conversion losses in both directions.'],
  links: [['battery-storage/pcs-inverters.html', 'PCS &amp; Inverters'], G('guide-grid-forming-vs-grid-following', 'Grid-Forming vs. Grid-Following Inverters'), C('bess-sizing', 'BESS Sizing Calculator'), G('guide-bess-c-rate', 'BESS C-Rate Explained')],
  see: ['grid-forming', 'dc-block', 'kva-vs-kw', 'c-rate'],
},
'pue': {
  t: 'PUE (Power Usage Effectiveness): Definition',
  more: ['Take everything a data center draws from the utility and divide it by what reaches the IT equipment. The result is PUE. At 1.5, each kilowatt of computing carries half a kilowatt of overhead for cooling, power conversion losses, lighting and the rest. At 1.2 the overhead is a fifth of a kilowatt.',
         'The figure is meaningful only as an average over a year, because it moves with the weather and with how full the facility is. A site that reports its best winter afternoon is reporting something else. It is also a measure of the building and not of the computing: a facility can improve its PUE by adding inefficient servers, since the IT load in the denominator grows while the overhead barely changes.'],
  points: ['PUE = total facility energy &divide; IT equipment energy, over the same period.', 'It says nothing about water use or the carbon intensity of the supply, which have their own metrics.'],
  links: [G('guide-pue-explained', 'PUE Explained'), C('pue', 'PUE Calculator'), G('guide-hot-aisle-vs-cold-aisle-containment', 'Hot Aisle vs. Cold Aisle Containment'), C('electricity-cost', 'Electricity Cost Calculator')],
  see: ['crah-crac', 'cdu', 'n-plus-1'],
},
'safe-harbor': {
  t: 'Safe Harbor (Construction): Definition',
  more: ['Tax credits for energy projects are often tied to the date construction begins. Because a large project takes years, the IRS has published tests for establishing that date before much is visibly built, and a project that meets one is said to have safe-harboured its eligibility under the rules in force at the time.',
         'The tests, the amounts involved and how long a project then has to finish have been revised by guidance and by legislation, so the current position should be taken from current sources. The reason the term appears in equipment discussions is that one long-standing route involves buying or starting manufacture of major equipment early. That is why transformers and other long-lead items are sometimes ordered well ahead of the rest of a project.'],
  points: ['Check current IRS guidance or a tax adviser; the rules have changed more than once.', 'Equipment bought for this purpose has to be stored, insured and still be suitable when the project is built.'],
  links: [G('guide-feoc-compliance', 'FEOC Compliance'), G('guide-transformer-lead-times', 'Why Transformer Lead Times Stretch'), ['lead-time-index.html', 'Lead-Time Index']],
  see: ['itc', 'feoc', 'domestic-content-bonus'],
},
'sccr': {
  t: 'SCCR (Short-Circuit Current Rating)',
  more: ['A control panel, a motor starter or a piece of HVAC equipment contains many components in the fault path: breakers, contactors, terminal blocks, drives. The short-circuit current rating is the fault current the whole assembly can be connected to without creating a fire or shock hazard, and it is marked on the nameplate.',
         'It is found by a weakest-link analysis. Each power component has its own rating, and unless a current-limiting device upstream can be shown to protect it, the lowest one sets the rating of the panel. A panel built with a 65 kA main breaker and one unprotected 5 kA terminal block is a 5 kA panel. The installer\'s job is then to confirm that the available fault current at that location does not exceed the marked figure.'],
  points: ['Interrupting rating belongs to one protective device; SCCR belongs to an assembly.', 'Equipment marked with a low default rating often cannot be installed close to a large transformer without added protection.'],
  links: [G('guide-interrupting-rating-vs-sccr', 'Interrupting Rating vs. SCCR'), C('fault-current', 'Fault Current Calculator'), G('guide-fully-rated-vs-series-rated', 'Fully Rated vs. Series Rated'), G('guide-short-circuit-studies-breaker-coordination', 'Short-Circuit Studies &amp; Coordination')],
  see: ['interrupting-rating', 'impedance', 'mccb', 'busway'],
},
'selective-coordination': {
  more: ['When a fault occurs, every protective device between it and the source sees the fault current. In a coordinated system the device immediately upstream of the fault opens first and the others stay closed, so only the faulted circuit is lost. Without coordination a fault on one branch can open a feeder or a main and take down everything it serves.',
         'It is achieved by making each upstream device slower than the one below it across the whole range of fault currents, which is checked by overlaying their time-current curves. The difficulty is at high fault currents, where breakers trip instantaneously and cannot wait for each other. That is solved with fuses, with breakers that have a short-time delay in place of an instantaneous trip, or with zone-selective interlocking, where breakers signal one another.'],
  points: ['Delaying upstream devices to gain coordination increases arc-flash energy, so the two aims have to be balanced.', 'Codes require it for certain systems, including emergency systems, legally required standby systems and elevators.'],
  links: [G('guide-short-circuit-studies-breaker-coordination', 'Short-Circuit Studies &amp; Coordination'), G('guide-fuse-vs-breaker', 'Fuse vs. Circuit Breaker'), G('guide-nec-240-87-arc-energy-reduction', 'NEC 240.87 Arc Energy Reduction'), C('fault-current', 'Fault Current Calculator')],
  see: ['interrupting-rating', 'incident-energy', 'mccb', 'sccr'],
},
'soc-soh': {
  t: 'SoC and SoH: State of Charge and Health',
  more: ['State of charge is the fuel gauge: the energy in the battery now, as a percentage of what it can hold now. State of health is the size of the tank: what it can hold now, as a percentage of what it held when new. A battery at 100 percent state of charge and 80 percent state of health is full, and holds four fifths of its original energy.',
         'Neither can be measured directly. The battery management system infers both from voltage, current and temperature, mainly by adding up the current that has flowed in and out and correcting the total when the battery rests. Errors accumulate, and they matter: operators keep margins at the top and bottom of the range to allow for them, which reduces the capacity that can be used.'],
  points: ['End of life is commonly defined as a state of health of 70 or 80 percent, depending on the contract.', 'State of charge also has to be balanced between cells, or the weakest cell limits the whole string.'],
  links: [G('guide-bess-augmentation', 'BESS Augmentation'), C('bess-sizing', 'BESS Sizing Calculator'), C('battery-runtime', 'Battery Runtime Calculator'), ['battery-storage/pcs-inverters.html', 'PCS &amp; Inverters']],
  see: ['c-rate', 'augmentation', 'lfp-nmc', 'dc-block'],
},
'ul-9540a': {
  t: 'UL 9540A: What the Test Method Covers',
  more: ['UL 9540A is a test method, and it does not have a pass or a fail. It measures what happens when a battery cell is deliberately forced into thermal runaway: at what temperature it vents, what gases come off and in what volume, and whether the failure spreads. The testing proceeds in stages, from a single cell to a module, then a complete unit, and where needed a full installation.',
         'The results are data, reported for others to judge. Fire codes and NFPA 855 use that data to decide how closely units may be spaced, how large a group may be, and what explosion control is required. A system whose unit-level test shows no spread to neighbouring units can be installed far more densely than the default limits allow, which is why the report is requested early in any project.'],
  points: ['UL 9540A is a test method. UL 9540, without the letter, is the safety standard a system is listed to.', 'A report applies to the exact configuration tested; a changed cell or enclosure can invalidate it.'],
  links: [G('guide-bess-fire-safety-nfpa-855', 'BESS Fire Safety: NFPA 855 &amp; UL 9540A'), ['battery-storage/bess-enclosures.html', 'BESS Enclosures'], ['battery-storage/balance-of-plant.html', 'BESS Balance of Plant'], ['battery-storage.html', 'Battery Storage Systems']],
  see: ['nfpa-855', 'lfp-nmc', 'dc-block'],
},
'vector-group': {
  t: 'Transformer Vector Group: Definition',
  more: ['The code has three parts. A capital letter gives the high-voltage winding connection: D for delta, Y for wye, Z for zigzag. A small letter gives the low-voltage connection in the same way, with n added if the neutral is brought out. A number gives the phase displacement as a clock position, each hour being 30 degrees, with the high-voltage phasor at twelve. Dyn11 is delta high side, wye low side with neutral, low voltage leading by 30 degrees.',
         'The displacement is a consequence of the connections and cannot be adjusted afterwards. It matters whenever two sources are joined. Transformers in parallel must have the same displacement, and so must any two supplies that can be tied together through a bus or a transfer switch; otherwise a voltage difference exists between them even with no load, and closing the tie produces a large circulating current.'],
  points: ['The clock notation is the IEC convention. North American practice describes the same thing as a standard 30-degree shift between delta and wye windings.', 'Only certain groups can be paralleled with each other, and a mismatch is not something a tap change can correct.'],
  links: [G('guide-delta-vs-wye', 'Delta vs. Wye'), G('guide-transformer-nameplate', 'How to Read a Transformer Nameplate'), C('three-phase-power', 'Three-Phase Power Calculator'), G('guide-pad-mount-vs-gsu-transformers', 'Pad-Mount vs. GSU Transformers')],
  see: ['impedance', 'bil', 'ansi-c57', 'k-factor'],
},
};
